function PageTitle({ title, onBack }) { return <div className="page-title"><button onClick={onBack}>←</button><h1>{title}</h1></div>; }
function Cart({ rtl, apiCatalog, items, count, onBack, onCheckout, onQuantityChange }) { const resolvedItems = cartProducts(items, apiCatalog); const subtotal = resolvedItems.reduce((sum, item) => sum + item.product.price * item.quantity, 0); const t = rtl ? { title: 'سلة التسوق', intro: 'راجع المنتجات وعنوان التوصيل وطريقة الدفع.', empty: 'السلة فاضية', emptyBody: 'أضف منتجات الشوكولاتة المفضلة عشان تكمل طلبك.', start: 'ابدأ التسوق', items: 'المنتجات', quantity: 'الكمية', each: 'للقطعة', summary: 'ملخص الطلب', subtotal: 'الإجمالي الفرعي', delivery: 'رسوم التوصيل', free: 'مجاني', total: 'الإجمالي', checkout: 'إتمام الطلب', increase: 'زيادة الكمية', decrease: 'تقليل الكمية', wholesale: 'الحد الأدنى للطلب', wholesaleBody: 'الحد الأدنى يحتاج موافقة المالك قبل تفعيل إتمام الطلب.', guest: 'يمكنك تصفح المنتجات والشراء كزائر — تسجيل الدخول وإنشاء الحساب اختياريان.' } : { title: 'Shopping cart', intro: 'Review your product, delivery address and payment method.', empty: 'Your cart is empty', emptyBody: 'Add your favorite chocolate products to complete your order.', start: 'Start shopping', items: 'Products', quantity: 'Quantity', each: 'each', summary: 'Order summary', subtotal: 'Products subtotal', delivery: 'Delivery fee', free: 'Free', total: 'Total', checkout: 'Proceed to checkout', increase: 'Increase quantity', decrease: 'Decrease quantity', wholesale: 'Minimum order quantity', wholesaleBody: 'The minimum order quantity needs owner approval before checkout is enabled.', guest: 'An account is optional, but checkout remains unavailable until the minimum order quantity is approved.' }; const names = rtl ? { '70% Dark Chocolate Bars': 'ألواح شوكولاتة دارك 70٪', 'Sea Salt Dark Chocolate': 'شوكولاتة دارك بملح البحر', 'Cocoa Nib Truffles': 'ترافل بحبيبات الكاكاو', 'Classic Praline Box': 'علبة هدايا' } : {}; return <main className="page cart-page">{!count ? <><PageTitle title={t.title} onBack={onBack} /><div className="empty"><div className="empty-icon">♧</div><h2>{t.empty}</h2><p>{t.emptyBody}</p><button className="button primary" onClick={onBack}>{t.start}</button></div></> : <><div className="cart-heading"><h1>{t.title}</h1><p>{t.intro}</p></div><div className="cart-layout"><section className="cart-products"><h2 className="cart-section-title">{t.items}</h2>{resolvedItems.map((item) => { const title = names[item.product.title] || item.product.title; return <article className="cart-item" key={item.product.id}><img src={`${A}${item.product.image}`} alt={title} /><div className="cart-item-copy"><b>{title}</b><small>{t.quantity}: {item.quantity}</small><span>EGP {item.product.price} {t.each}</span><div className="cart-item-quantity"><button type="button" aria-label={t.decrease} onClick={() => onQuantityChange(item.productId, -1)}>−</button><strong>{item.quantity}</strong><button type="button" aria-label={t.increase} onClick={() => onQuantityChange(item.productId, 1)}>+</button></div></div><strong>EGP {item.product.price * item.quantity}</strong></article>; })}<div className="cart-wholesale-note"><b>{t.wholesale}</b><small>{t.wholesaleBody}</small></div></section><aside className="cart-summary"><h2>{t.summary}</h2><div><span>{t.subtotal}</span><b>EGP {subtotal}</b></div><div><span>{t.delivery}</span><b className="green">{t.free}</b></div><div className="cart-total"><strong>{t.total}</strong><strong>EGP {subtotal}</strong></div><button className="button primary" onClick={onCheckout}>{t.checkout}</button></aside></div><p className="cart-guest-note">{t.guest}</p></>}</main>; }
function Checkout({ rtl, apiCatalog, token, address, items, count, onBack, onAddress, onPayment, onSessionExpired, onPlaceOrder }) { const [submitting, setSubmitting] = useState(false); const [error, setError] = useState(''); const resolvedItems = cartProducts(items, apiCatalog); const subtotal = resolvedItems.reduce((sum, item) => sum + item.product.price * item.quantity, 0); const quantity = resolvedItems.reduce((sum, item) => sum + item.quantity, 0) || count || 1; const t = rtl ? {title:'إتمام الطلب',cart:'السلة',review:'المراجعة',confirm:'التأكيد',address:'عنوان التوصيل',edit:'تعديل',payment:'طريقة الدفع',change:'تغيير',items:'المنتجات',qty:'الكمية',wholesale:'للجملة فقط · حد أدنى إلزامي',current:'الكمية الحالية:',minimum:'الحد الأدنى للطلب: في انتظار موافقة المالك.',unavailable:'لا يمكن إتمام الطلب قبل اعتماد الحد الأدنى.',subtotal:'الإجمالي الفرعي',delivery:'رسوم التوصيل',free:'مجاني',paymentAvailable:'متاح',total:'الإجمالي',place:'تأكيد الطلب',guestPlace:'تأكيد الطلب كزائر',home:'المنزل',cod:'الدفع عند الاستلام'} : {title:'Checkout',cart:'Cart',review:'Review',confirm:'Confirmation',address:'Delivery address',edit:'Edit',payment:'Payment method',change:'Change',items:'Order items',qty:'Quantity',wholesale:'Wholesale only · Mandatory minimum',current:'Current quantity:',minimum:'Minimum order quantity: pending owner approval.',unavailable:'Checkout is unavailable unless MOQ is met.',subtotal:'Subtotal',delivery:'Delivery fee',free:'Free',paymentAvailable:'Available',total:'Total amount',place:'Place order',guestPlace:'Place order as guest',home:'Home',cod:'Cash on delivery'}; const names = rtl ? { '70% Dark Chocolate Bars': 'ألواح شوكولاتة دارك 70٪', 'Sea Salt Dark Chocolate': 'شوكولاتة دارك بملح البحر', 'Cocoa Nib Truffles': 'ترافل بحبيبات الكاكاو', 'Classic Praline Box': 'علبة برالين كلاسيكية', 'Gift box': 'علبة هدايا' } : {}; const submit = async () => { setSubmitting(true); setError(''); try { await onPlaceOrder(); } catch (err) { if (err.status === 401) { onSessionExpired(); return; } setError(err.message); } finally { setSubmitting(false); } }; return <main className="page checkout checkout-page"><PageTitle title={t.title} onBack={onBack} /><div className="steps"><b>✓<small>{t.cart}</small></b><b>●<small>{t.review}</small></b><span>○<small>{t.confirm}</small></span></div><div className="checkout-grid"><div className="checkout-main"><Section title={t.address} action={t.edit} onClick={onAddress}><div className="field"><b>⌖ {t.home}</b><small>{address}</small></div></Section><Section title={t.payment} action={t.change} onClick={onPayment}><div className="field"><b>▣ {t.cod}</b><small>{t.paymentAvailable}</small></div></Section><Section title={t.items}>{resolvedItems.map((item) => { const title = names[item.product.title] || item.product.title; return <div className="order-row" key={item.product.id}><img src={`${A}${item.product.image}`} alt={title} /><div><b>{title}</b><small>{t.qty}: {item.quantity}</small></div><strong>{item.product.price * item.quantity} EGP</strong></div>; })}</Section><div className="notice"><b>{t.wholesale}</b><p>{t.current} {quantity}<br/>{t.minimum}<br/>{t.unavailable}</p></div></div><aside className="checkout-summary"><h2>{t.total}</h2><div><span>{t.subtotal}</span><b>{subtotal} EGP</b></div><div><span>{t.delivery}</span><b className="green">{t.free}</b></div><div className="checkout-total"><strong>{t.total}</strong><strong>{subtotal} EGP</strong></div>{error && <p className="error-text" role="alert">{error}</p>}<button className="button primary" disabled={submitting} onClick={submit}>{submitting ? (rtl ? 'جارٍ التأكيد...' : 'Placing order...') : (token ? t.place : t.guestPlace)}</button></aside></div></main>; }
