function Address({ rtl, value, onBack, onSave }) { const parts = value.split(',').map((part) => part.trim()).filter(Boolean); const legacyExtra = parts.length <= 3 ? parts.slice(2).join(', ') : ''; const [city, setCity] = useState(parts[0] || (rtl ? 'الرياض' : 'Riyadh')); const [street, setStreet] = useState(parts[1] || (rtl ? 'النرجس' : 'Al Narjis')); const [building, setBuilding] = useState(parts.length > 3 ? parts[2] : ''); const [details, setDetails] = useState(parts.length > 3 ? parts.slice(3).join(', ') : (legacyExtra || (rtl ? 'شارع الأمير سعود' : 'Prince Saud Street'))); const [addressLabel, setAddressLabel] = useState('home'); const t = rtl ? { title: 'عنوان التوصيل', location: 'الموقع الحالي', details: 'تفاصيل العنوان', body: 'أكد موقع التوصيل وأكمل بيانات العنوان.', city: 'المدينة والحي', street: 'اسم الشارع', building: 'رقم المبنى', extra: 'تفاصيل إضافية (اختياري)', saveAs: 'حفظ العنوان باسم', home: 'المنزل', work: 'العمل', other: 'آخر', save: 'حفظ واستخدام العنوان' } : { title: 'Delivery address', location: 'Current location', details: 'Address details', body: 'Confirm the delivery location and complete the address details.', city: 'City and neighborhood', street: 'Street name', building: 'Building number', extra: 'Additional details (optional)', saveAs: 'Save address as', home: 'Home', work: 'Work', other: 'Other', save: 'Save and use address' }; const save = () => onSave([city, street, building, details].map((part) => part.trim()).filter(Boolean).join(', ')); return <main className="page address-page"><PageTitle title={t.title} onBack={onBack} /><div className="address-hero"><span className="address-pin">⌖</span><small>{t.location}</small></div><div className="address-form"><h2>{t.details}</h2><p className="muted">{t.body}</p><label className="address-field"><span>{t.city}</span><input required name="city" autoComplete="address-level2" value={city} onChange={(event) => setCity(event.target.value)} placeholder={t.city} /></label><div className="form-row"><label className="address-field"><span>{t.street}</span><input required name="street" autoComplete="street-address" value={street} onChange={(event) => setStreet(event.target.value)} placeholder={t.street} /></label><label className="address-field"><span>{t.building}</span><input name="building" autoComplete="address-line2" value={building} onChange={(event) => setBuilding(event.target.value)} placeholder={t.building} /></label></div><label className="address-field"><span>{t.extra}</span><input name="address-extra" autoComplete="address-line3" value={details} onChange={(event) => setDetails(event.target.value)} placeholder={t.extra} /></label><h3>{t.saveAs}</h3><div className="chips"><button type="button" className={addressLabel === 'home' ? 'selected' : ''} onClick={() => setAddressLabel('home')}>{t.home}</button><button type="button" className={addressLabel === 'work' ? 'selected' : ''} onClick={() => setAddressLabel('work')}>{t.work}</button><button type="button" className={addressLabel === 'other' ? 'selected' : ''} onClick={() => setAddressLabel('other')}>{t.other}</button></div><button className="button primary" onClick={save}>{t.save}</button></div></main>; }
function Payment({ rtl, onBack }) { const [selected, setSelected] = useState('cash'); const t = rtl ? { title: 'طريقة الدفع', available: 'الدفع عند الاستلام متاح', unavailable: 'طرق الدفع الأخرى غير متاحة حاليًا.', saved: 'البطاقات المحفوظة', unavailableShort: 'غير متاح حاليًا', other: 'طرق دفع أخرى', pay: 'غير متاح', cash: 'الدفع عند الاستلام', confirm: 'تأكيد طريقة الدفع', card: 'بطاقة محفوظة', add: 'إضافة بطاقة جديدة' } : { title: 'Payment method', available: 'Cash on delivery is available', unavailable: 'Other payment methods are currently unavailable.', saved: 'Saved cards', unavailableShort: 'Currently unavailable', other: 'Other payment methods', pay: 'Unavailable', cash: 'Cash on delivery', confirm: 'Confirm payment method', card: 'Saved card', add: 'Add a new card' }; const unavailableCards = ['Mada ·•••• 1234', 'Visa ·•••• 9114']; return <main className="page payment-page"><PageTitle title={t.title} onBack={onBack} /><div className="notice success"><b>{t.available}</b><p>{t.unavailable}</p></div><section className="payment-group"><h2>{t.saved}</h2>{unavailableCards.map((item) => <div className="payment-row is-disabled" key={item}><span className="payment-method-icon">▣</span><div><b>{item}</b><small>{t.card}</small></div><small>{t.unavailableShort}</small></div>)}<div className="payment-row is-disabled"><span className="payment-method-icon">＋</span><div><b>{t.add}</b><small>{t.saved}</small></div><small>{t.unavailableShort}</small></div></section><section className="payment-group"><h2>{t.other}</h2><button type="button" className={`payment-row ${selected === 'cash' ? 'selected' : ''}`} onClick={() => setSelected('cash')}><span className="payment-method-icon">▣</span><div><b>{t.cash}</b><small>{t.available}</small></div><span className="payment-radio">{selected === 'cash' ? '●' : '○'}</span></button><div className="payment-row is-disabled"><span className="payment-method-icon">◉</span><div><b>Apple Pay</b><small>{t.pay}</small></div><small>{t.unavailableShort}</small></div></section><button className="button primary" onClick={onBack}>{t.confirm}</button></main>; }
