function SettingsLocalized({ rtl, dark, onTheme, onLanguage, onBack }) { const t = rtl ? { title: 'الإعدادات', prefs: 'التفضيلات', language: 'اللغة', arabic: 'العربية', english: 'English', notifications: 'الإشعارات', on: 'مفعلة', theme: 'المظهر', light: 'فاتح', dark: 'داكن', support: 'المساعدة', help: 'مركز المساعدة', contact: 'تواصل معنا', unavailable: 'متاح قريبًا' } : { title: 'Settings', prefs: 'Preferences', language: 'Language', arabic: 'العربية', english: 'English', notifications: 'Notifications', on: 'On', theme: 'Theme', light: 'Light', dark: 'Dark', support: 'Support', help: 'Help center', contact: 'Contact us', unavailable: 'Coming soon' }; return <main className="page settings-page"><PageTitle title={t.title} onBack={onBack} /><div className="settings-group"><h2>{t.prefs}</h2><button className="menu-row settings-action" onClick={() => onLanguage(!rtl)}><span className="settings-row-icon">文</span><span className="settings-row-copy"><b>{t.language}</b><small>{rtl ? t.arabic : t.english}</small></span><span className="settings-row-value">{rtl ? t.english : t.arabic} ›</span></button><div className="menu-row settings-action is-static"><span className="settings-row-icon">◔</span><span className="settings-row-copy"><b>{t.notifications}</b><small>{t.unavailable}</small></span><span className="settings-row-value">{t.on} ›</span></div><button className="menu-row settings-action" onClick={() => onTheme(!dark)}><span className="settings-row-icon">◐</span><span className="settings-row-copy"><b>{t.theme}</b><small>{dark ? t.dark : t.light}</small></span><span className="settings-row-value">{dark ? t.light : t.dark} ›</span></button></div><div className="settings-group"><h2>{t.support}</h2><div className="menu-row settings-action is-static"><span className="settings-row-icon">?</span><span className="settings-row-copy"><b>{t.help}</b><small>{t.unavailable}</small></span><span className="settings-row-value">›</span></div><div className="menu-row settings-action is-static"><span className="settings-row-icon">@</span><span className="settings-row-copy"><b>{t.contact}</b><small>{t.unavailable}</small></span><span className="settings-row-value">›</span></div></div></main>; }
function OrderReceivedLocalized({ rtl, order, onHome, onOrders }) { const orderNo = order?.orderNo || '—'; const total = order?.total ?? 0; const date = order?.createdAt ? new Intl.DateTimeFormat(rtl ? 'ar-EG' : 'en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(order.createdAt)) : '—'; const t = rtl ? { eyebrow: 'شكرًا لطلبك', title: 'تم استلام الطلب', body: `تم تسجيل طلبك #${orderNo} بنجاح. هنفضل نبلغك بكل تحديث.`, status: 'الطلب قيد التجهيز', estimate: 'التوصيل المتوقع', payment: 'الدفع عند الاستلام', total: 'الإجمالي', view: 'عرض تفاصيل الطلب', shop: 'كمل التسوق' } : { eyebrow: 'Thank you for your order', title: 'Order received', body: `Your order #${orderNo} has been placed successfully. We will keep you updated as it moves forward.`, status: 'Preparing your order', estimate: 'Estimated delivery', payment: 'Cash on delivery', total: 'Total', view: 'View order details', shop: 'Continue shopping' }; return <main className="page received-page"><div className="received-icon">✓</div><p className="eyebrow">{t.eyebrow}</p><h1>{t.title}</h1><p className="muted received-copy">{t.body}</p><section className="received-summary"><div className="received-summary-head"><div><small>{rtl ? 'رقم الطلب' : 'Order number'}</small><b>#{orderNo}</b></div><span className="received-status">{t.status}</span></div><div className="received-summary-grid"><div><small>{t.estimate}</small><b>{date}</b></div><div><small>{t.payment}</small><b>{t.payment}</b></div><div><small>{t.total}</small><b>{total} EGP</b></div></div></section><button className="button primary" onClick={onOrders}>{t.view}</button><button className="text-button" onClick={onHome}>{t.shop}</button></main>; }
function AdminDashboardLocalized({ rtl, token, onSessionExpired, onBack }) {
  const t = rtl ? {
    brand: 'لوحة الإدارة', menu: 'القائمة الرئيسية', overview: 'نظرة عامة', orders: 'الطلبات', products: 'المنتجات والمخزون', categories: 'التصنيفات', makers: 'الصنّاع والموردون', customers: 'العملاء والحسابات', discounts: 'الخصومات والكوبونات', loyalty: 'نقاط الولاء', delivery: 'سياسة التوصيل', settings: 'إعدادات المتجر', title: 'نظرة عامة', subtitle: 'إدارة المنتجات والطلبات والصنّاع — مساحة تشغيلية لمتجر Choco Delight.', notConnected: 'غير متصل', displayedMakers: 'الصنّاع المعروضون', interfaceCategories: 'تصنيفات الواجهة', sampleProducts: 'منتجات الكتالوج', comparison: 'مقارنة الكتالوج حسب التصنيف', management: 'إدارة المنتجات', summary: 'ملخص طلب تجريبي', decision: 'قرارات تنتظر اعتماد صاحب المشروع', sampleNote: 'عينة تصميمية — ليست طلبًا حقيقيًا', product: 'المنتج', category: 'التصنيف', price: 'السعر', status: 'الحالة', pending: 'بانتظار المراجعة', available: 'متاح', noAccess: 'ليس لديك صلاحية الدخول للوحة الإدارة', login: 'يجب تسجيل الدخول بحساب مسؤول للاستمرار', loading: 'جارٍ تحميل لوحة الإدارة...'
  } : {
    brand: 'Admin dashboard', menu: 'Main menu', overview: 'Overview', orders: 'Orders', products: 'Products & inventory', categories: 'Categories', makers: 'Makers & suppliers', customers: 'Customers & accounts', discounts: 'Discounts & coupons', loyalty: 'Loyalty points', delivery: 'Delivery policy', settings: 'Store settings', title: 'Overview', subtitle: 'Manage your products, orders and makers — your operational space for Choco Delight.', notConnected: 'Not connected', displayedMakers: 'Displayed makers', interfaceCategories: 'Interface categories', sampleProducts: 'Catalog sample products', comparison: 'Catalog comparison by category', management: 'Product management', summary: 'Sample order summary', decision: 'Decisions pending owner approval', sampleNote: 'Design-only sample — not a real order', product: 'Product', category: 'Category', price: 'Price', status: 'Status', pending: 'Pending review', available: 'Available', noAccess: 'You do not have admin access', login: 'Sign in with an admin account to continue', loading: 'Loading admin dashboard...'
  };
  const [data, setData] = useState(null);
  const [error, setError] = useState('');
  useEffect(() => { if (!token) return; fetchAdminDashboard(token).then(setData).catch((err) => { if (err.status === 401) { onSessionExpired(); return; } setError(err.status === 403 ? t.noAccess : err.message); }); }, [token, onSessionExpired, t.noAccess]);
  const categories = data ? Object.entries(data.products.reduce((result, item) => { const key = item.category?.name || (rtl ? 'أخرى' : 'Other'); result[key] = (result[key] || 0) + 1; return result; }, {})) : [];
  const maxCategoryCount = Math.max(1, ...categories.map(([, count]) => count));
  const menu = [t.overview, t.orders, t.products, t.categories, t.makers, t.customers, t.discounts, t.loyalty, t.delivery, t.settings];
  return <main className={`admin-figma-page ${rtl ? 'admin-figma-rtl' : ''}`}>
    {!token && <p className="admin-figma-message">{t.login}</p>}
    {token && !data && !error && <p className="admin-figma-message">{t.loading}</p>}
    {error && <p className="admin-figma-message" role="alert">{error}</p>}
    {data && <>
      <header className="admin-figma-topbar"><button className="admin-figma-back" onClick={onBack} aria-label={rtl ? 'العودة' : 'Back'}>‹</button><b>{t.brand}</b><span>Choco Delight Marketplace</span></header>
      <div className="admin-figma-layout">
        <aside className="admin-figma-sidebar"><strong>{t.menu}</strong>{menu.map((item, index) => <button className={index === 0 ? 'selected' : ''} key={item}>{item}</button>)}</aside>
        <section className="admin-figma-content"><div className="admin-figma-heading"><div><h1>{t.title}</h1><p>{t.subtitle}</p></div></div>
          <div className="admin-figma-metrics"><div><small>Order status</small><b>{t.notConnected}</b><span>Live order connection</span></div><div><small>{t.displayedMakers}</small><b>—</b><span>Connect maker data</span></div><div><small>{t.interfaceCategories}</small><b>{categories.length}</b><span>Taxonomy in catalog</span></div><div><small>{t.sampleProducts}</small><b>{data.products.length}</b><span>Active products shown</span></div></div>
          <div className="admin-figma-grid"><section className="admin-figma-card admin-figma-chart"><h2>{t.comparison}</h2><p>Products currently represented in the catalog.</p>{categories.slice(0, 5).map(([name, count]) => <div className="admin-figma-bar-row" key={name}><span>{name}</span><i><em style={{ width: `${(count / maxCategoryCount) * 100}%` }} /></i><b>{count}</b></div>)}</section>
            <section className="admin-figma-card admin-figma-table"><h2>{t.management}</h2><p>Products currently connected to inventory and pricing.</p><div className="admin-figma-table-head"><span>{t.product}</span><span>{t.category}</span><span>{t.price}</span><span>{t.status}</span></div>{data.products.slice(0, 7).map((product) => <div className="admin-figma-table-row" key={product.id}><b>{product.title}</b><span>{product.category?.name || '—'}</span><span>{product.price} EGP</span><span>{t.pending}</span></div>)}</section>
            <section className="admin-figma-card admin-figma-order"><h2>{t.summary}</h2><small>{t.sampleNote}</small><p>Order number: #DEMO-XXXX</p><b>EGP {Number(data.products[0]?.price || 0).toLocaleString()} · Cash on delivery</b><span>{t.pending}</span></section>
          </div><section className="admin-figma-decision"><h2>{t.decision}</h2><p>MOQ and availability rules, product pricing and marketplace settings are waiting for owner approval.</p></section>
        </section>
      </div>
    </>}
  </main>;
}
function Footer({ page, rtl, onNavigate }) { return <footer><span>© 2026 Choco Delight</span><div><a onClick={() => onNavigate('home')}>{rtl ? 'تسوق' : 'Shop'}</a><a onClick={() => onNavigate('categories')}>{rtl ? 'المجموعات' : 'Collections'}</a><a>{rtl ? 'للجملة' : 'Wholesale'}</a><a>{rtl ? 'تواصل معنا' : 'Contact'}</a></div></footer>; }

createRoot(document.getElementById('root')).render(<App />);
